ALTER TABLE stable_boxes ADD CONSTRAINT ck_stable_capacity CHECK (capacity > 0);
ALTER TABLE horses ADD CONSTRAINT ck_horse_name CHECK (length(trim(horse_name)) > 0);
ALTER TABLE horses ADD CONSTRAINT ck_horse_weight CHECK (current_weight_kg > 0);
ALTER TABLE horses ADD CONSTRAINT ck_horse_readiness CHECK (readiness_status IN ('Ready', 'NotReady', 'Unknown'));
ALTER TABLE horses ADD CONSTRAINT ck_horse_lock_level CHECK (lock_level IN ('Warning', 'Critical'));
